INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-paranjape', 'Paranjape Schemes', 'paranjape-schemes', '/images/builders/paranjape-official.webp', 'https://www.pscl.in/wp-content/uploads/2025/10/ANK440_7834a_LR.webp', 'Founded in 1987 by Shrikant and Shashank Paranjape, Paranjape Schemes (Construction) Ltd (PSCL) is one of Maharashtra''s most pioneering real estate developers with over 200 delivered projects, 20,000+ satisfied families, iconic mega townships like Blue Ridge (Hinjewadi) and Forest Trails (Bhugaon), and pioneer senior citizen living communities under the Athashri brand across Pune and Mumbai MMR.', 1987, 200, 25, 9.7, 1, 20, '["Hinjewadi", "Bavdhan", "Baner", "Khed Shivapur", "Karve Road", "Bandra East", "Andheri West", "Thane West", "Shrivardhan-Diveagar"]');
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-hiranandani', 'Hiranandani Group', 'hiranandani-group', '/images/builders/hiranandani-official.webp', 'https://www.hiranandani.com/img/gallery/gallery-powai-castle-rock-a/01.jpg', 'Hiranandani Group is one of India''s most prestigious real estate conglomerates, renowned for pioneering integrated mega-townships like Hiranandani Gardens Powai and Hiranandani Estate Thane. Founded in 1978 by Dr. Niranjan Hiranandani, the group has transformed urban living across Maharashtra with neoclassical architecture, world-class social infrastructure, lush green environments, and impeccable engineering.', 1978, 65, 18, 4.9, 1, 46, '["Powai", "Thane", "Panvel", "Kandivali", "Chembur", "Pune"]');
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-della', 'Della Townships', 'della-townships', '/images/builders/della-official.webp', 'https://www.dellaresorts.com/new-updated-image/enclave-villa-resort.webp', 'Della Townships and Luxury Villas, conceptualized and designed by visionary architect Jimmy Mistry, represents the pinnacle of experiential hillside living and ultra-luxury second homes in Maharashtra. Spread across scenic hill slopes in Kunegaon, Lonavala and Khandala, Della offers fully serviced bespoke villas integrated with 24x7 5-star resort hospitality, private heated pools, fine-dining restaurants, and India''s premier adventure sports park.', 1996, 14, 5, 4.9, 1, 28, '["Kunegaon", "Lonavala", "Khandala", "Sahyadri Hills"]');
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-oberoi', 'Oberoi Realty', 'oberoi-realty', '/images/builders/oberoi-realty.svg', 'https://www.oberoirealty.com/assets/images/home-banner-desktop.jpg', 'Oberoi Realty is one of India''s preeminent ultra-luxury real estate developers, renowned for iconic skyline landmarks, five-star hospitality finishes, and impeccable engineering in Mumbai & Thane.', 1980, 45, 8, 98, 1, 20, '["Goregaon East", "Borivali East", "Kolshet Road", "Mulund West", "Worli"]');
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-runwal', 'Runwal Group', 'runwal-group', '/images/builders/runwal.svg', 'https://www.runwal.com/images/banner.jpg', 'Established in 1978, Runwal Group has delivered over 50 landmark residential and retail developments across Mumbai, Thane, and MMR with a steadfast commitment to customer trust and lifestyle delivery.', 1978, 65, 12, 94, 1, 20, '["Kanjurmarg", "Manpada", "Mulund", "Ghatkopar", "Chembur"]');
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-raymond', 'Raymond Realty', 'raymond-realty', '/images/builders/raymond-realty.svg', 'https://www.raymondrealty.in/assets/images/banner.jpg', 'Raymond Realty brings the legendary 97-year trust of the Raymond Group into real estate, delivering pioneering design, expansive landscaped habitats, and precision engineering across Pokhran Road, Thane.', 2019, 12, 6, 95, 1, 20, '["Pokhran Road No. 1", "Pokhran Road No. 2", "Bandra East", "Thane West"]');
