INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-piramal', 'Piramal Realty', 'piramal-realty', '/images/builders/piramal-realty.svg', 'https://www.piramalrealty.com/images/banner.jpg', 'Piramal Realty, the real estate development arm of the Piramal Group, sets global benchmarks in architectural excellence, green sustainability, and gold-standard luxury across South Mumbai and Mulund.', 2012, 18, 5, 97, 1, 20, '["Mulund West", "Mahalaxmi", "Byculla", "Thane"]');
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, trust_score, is_verified, experience, locations) VALUES ('b-dosti', 'Dosti Realty', 'dosti-realty', '/images/builders/dosti-realty.svg', 'https://www.dostirealty.com/images/banner.jpg', 'With over 4 decades of experience and more than 120 delivered properties, Dosti Realty is synonymous with value-driven community living, modern amenities, and timely delivery across Thane, Wadala, and Mumbai.', 1980, 125, 14, 93, 1, 20, '["Balkum", "Wadala", "Shilphata", "Thane West"]');
