INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city) VALUES ('p-mahindra-rivenza', 'Mahindra Rivenza', 'mahindra-rivenza', 'b-mahindra', 'Nande', '₹89 L - ₹2.19 Cr', '₹89 L', '["2 BHK", "3 BHK", "4 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/85f1c6ec-62f7-4537-bf61-e5aa7d43887a/gallery/mvf38h2x-2l6xoo.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/85f1c6ec-62f7-4537-bf61-e5aa7d43887a/gallery/mvf38h2x-2l6xoo.webp', 'https://keystoneliv.com/public/uploads/property/ugU2mSy6BbqdiWgd8BB1RXRyQnRK5gqL2KtUlB81.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/neQCNkziS5bgoqGRmAb7yybVwaAKDFIUsnKt9779.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp", "https://keystoneliv.com/public/uploads/property/zp0VEmpHjp3nxN9ZDMZAsjt8sftwy04Pt0zchCPr.webp"]', 'Mahindra Rivenza by Mahindra Lifespaces is a ~13.46-acre gated community in Baner Annex – village Nande, off the Baner–Hinjawadi Road, between Mahalunge and Hinjawadi, with the Mula river and hills alongside. The launch covers six high-rise towers (T1–T6) with 1,236 homes in RERA-registered Phase 1 and Phase 2, and there are dedicated towers for 2, 3 and 4 BHK residences. Homes range from 2 BHK of 688–855 sq ft and 3 BHK of 995–1,206 sq ft to 4 BHK of 1,615–1,650 sq ft (total area including balconies and utility). The plans include walk-in wardrobes in the 2 and 3 BHK homes, decks off the living rooms, and a butterfly 4 BHK layout with a servant room. Over 9 acres are landscaped greens, and more than 2.65 lakh sq ft is given to amenities – two clubhouses, a swimming pool with a sunken bar, futsal, pickleball, badminton and squash courts, a skating rink, a gym, yoga lawns and decks, a library, a barbeque deck and stargazing hammocks. The project is IGBC Gold pre-certified. Delhi Public School Hinjawadi is next door, Hinjawadi Phase 1 is about 6 km away and the Balewadi metro station (Line 3) about 5.7 km. Prices start from ₹89 Lakh for a 2 BHK on a construction-linked plan, and RERA possession is December 2031. Enquire for the brochure, floor plans and EOI benefits.', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Covered Parking"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PR1261012602102"}, {"label": "Direct Starting Price", "value": "₹89 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Nande, Pune"}]', '["MahaRERA: PR1261012602102", "0% Brokerage & Direct Builder Booking", "Nande Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'PR1261012602102', 12936, 'Verified', 'Pune');
