]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100050692"}, {"label": "Direct Starting Price", "value": "₹1.85 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Nigdi, Pune"}]', '["MahaRERA: P52100050692", "0% Brokerage & Direct Builder Booking", "Nigdi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100050692', 14835, 'Verified', 'Pune');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city) VALUES ('p-arkaay-towers', 'Arkaay Towers', 'arkaay-towers', 'b-arkaay-developers', 'Tathawade', '₹96 L - ₹1.30 Cr', '₹96 L', '["2 BHK", "3 BHK"]', 'Ready to Move', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/c8b7b2c5-d220-4557-b4d5-b02d2662c19c/gallery/mrqr33d9-b8r2m3.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/c8b7b2c5-d220-4557-b4d5-b02d2662c19c/gallery/mrqr33d9-b8r2m3.webp', 'https://keystoneliv.com/public/uploads/property/ugU2mSy6BbqdiWgd8BB1RXRyQnRK5gqL2KtUlB81.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/neQCNkziS5bgoqGRmAb7yybVwaAKDFIUsnKt9779.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp", "https://keystoneliv.com/public/uploads/property/zp0VEmpHjp3nxN9ZDMZAsjt8sftwy04Pt0zchCPr.webp"]', 'Arkaay Towers by Rajwardhan Group is a RERA-registered residential project in Tathawade, Pune, offering premium 2 and 3 BHK homes with carpet areas from 777 to 1,050 sq ft. Thoughtfully designed with modern amenities, the towers enjoy excellent connectivity to Hinjewadi, Wakad and the Mumbai–Pune Expressway, placing the IT corridor, schools, hospitals and retail within easy reach. Prices start from ₹96 Lakh, with possession scheduled for March 2029. Whether you are looking for a comfortable family residence or a smart investment in one of Pune''s most active growth corridors, Arkaay Towers offers a well-connected, future-ready address. Enquire for floor plans, pricing and availability.', '["CCTV Surveillance", "Rainwater Harvesting", "Power Backup", "24x7 Security", "Covered Parking", "Kids'' Play Area", "Yoga Deck", "EV Charging"]', '[{"label": "Project Status", "value": "Ready to Move"}, {"label": "MahaRERA ID", "value": "PM1260002502454"}, {"label": "Direct Starting Price", "value": "₹96 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Tathawade, Pune"}]', '["MahaRERA: PM1260002502454", "0% Brokerage & Direct Builder Booking", "Tathawade Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'PM1260002502454', 12355, 'Verified', 'Pune');
