INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city) VALUES ('p-santiago-sunrise', 'Santiago Sunrise', 'santiago-sunrise', 'b-santiago-realty', 'Aundh', '₹80 L - ₹1.07 Cr', '₹80 L', '["2 BHK", "3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghm8cf-4dt4kg.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghm8cf-4dt4kg.webp', 'https://keystoneliv.com/public/uploads/property/ugU2mSy6BbqdiWgd8BB1RXRyQnRK5gqL2KtUlB81.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/neQCNkziS5bgoqGRmAb7yybVwaAKDFIUsnKt9779.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp", "https://keystoneliv.com/public/uploads/property/zp0VEmpHjp3nxN9ZDMZAsjt8sftwy04Pt0zchCPr.webp"]', 'Santiago Sunrise is a residential project by Santiago Realty (Santiago Realtech Ventures) on Survey No. 12/1, Plot No. 74 in Old Sangvi, Pune 411027, which the developer also describes as New Aundh. It is a single-tower development on about 0.28 acre, launched in October 2024. The developer lists 2 BHK homes of about 683 and 693 sq ft and 3 BHK homes of about 908 and 991 sq ft, designed to be Vastu-compliant with covered parking for each flat, large balconies and three-side open views. Listed starting prices are around Rs 80 lakh for 2 BHK and Rs 1.07 crore for 3 BHK; please contact the Pune Home sales team for the current price sheet. Amenities include a gymnasium, kids'' play area, yoga area, jogging track, landscaped garden, rainwater harvesting, CCTV surveillance, 24x7 security and power backup. Listings place Dolphins International School and Dr Khandge Hospital about 300 m away, a park about 600 m, and Dapodi metro station about 2.5 km away. The project is registered under MahaRERA number P52100077792 with a possession date of December 2027.', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "P52100077792"}, {"label": "Direct Starting Price", "value": "₹80 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Aundh, Pune"}]', '["MahaRERA: P52100077792", "0% Brokerage & Direct Builder Booking", "Aundh Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100077792', 11713, 'Verified', 'Pune');
