INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city) VALUES ('p-tulip-infinity-avana', 'Tulip Infinity Avana', 'tulip-infinity-avana', 'b-tulip-group', 'Punawale', '₹1.04 Cr - ₹2.20 Cr', '₹1.04 Cr', '["2 BHK", "3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc6xbx-17wr8.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc6xbx-17wr8.webp', 'https://keystoneliv.com/public/uploads/property/ugU2mSy6BbqdiWgd8BB1RXRyQnRK5gqL2KtUlB81.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/neQCNkziS5bgoqGRmAb7yybVwaAKDFIUsnKt9779.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp", "https://keystoneliv.com/public/uploads/property/zp0VEmpHjp3nxN9ZDMZAsjt8sftwy04Pt0zchCPr.webp"]', 'Tulip Infinity Avana is a residential project by Tulip Group, now Varma Corp, on the Aundh-Ravet BRTS Road at Vishnu Dev Nagar, Punawale, on the Tathawade side of Pimpri-Chinchwad, Pune 411033. It is planned as four high-rise towers of about 33 floors on roughly 3.2 acres. Homes are 2, 3 and 4 BHK with carpet areas of about 796 to 938 sq ft, 1,045 to 1,266 sq ft and 1,485 sq ft. The developer publishes all-inclusive estimates from about 1.04 crore for a 2 BHK, 1.40 crore for a 3 BHK and 2.20 crore for a 4 BHK; confirm the current cost sheet. Amenities include two swimming pools, a 40-seat mini theatre, a multi-zone gymnasium, rooftop co-working spaces, a library, a half basketball court and landscaped gardens. Listing sites place Gagangiri Hospital about 0.5 km away, Jeevan Shikshan Vidya Mandir school 0.6 km and the Mumbai-Bangalore highway about 1.5 km. The project is registered with MahaRERA under P52100047662 with possession due in December 2026.', '["Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100047662"}, {"label": "Direct Starting Price", "value": "₹1.04 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Punawale, Pune"}]', '["MahaRERA: P52100047662", "0% Brokerage & Direct Builder Booking", "Punawale Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100047662', 13065, 'Verified', 'Pune');
