, '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PR1261012501027"}, {"label": "Direct Starting Price", "value": "₹94 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Punawale, Pune"}]', '["MahaRERA: PR1261012501027", "0% Brokerage & Direct Builder Booking", "Punawale Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'PR1261012501027', 11604, 'Verified', 'Pune');
