ons.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Sports Court", "Jogging Track", "Swimming Pool", "Power Backup"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100055932"}, {"label": "Direct Starting Price", "value": "₹96 L"}, {"label": "Configurations", "value": "2 BHK, 2.5 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Moshi, Pune"}]', '["MahaRERA: P52100055932", "0% Brokerage & Direct Builder Booking", "Moshi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100055932', 10000, 'Verified', 'Pune');
