INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city) VALUES ('p-navyam', 'Navyam', 'navyam', 'b-kiwale-realty-llp', 'Ravet', '₹85 L - ₹1.15 Cr', '₹85 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '31 December 2029', 'https://punehome.in/storage/v1/object/public/project-media/projects/b80dcfb1-9a8c-4126-8545-75666ce1fed6/gallery/mvfblt6r-667qht.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/b80dcfb1-9a8c-4126-8545-75666ce1fed6/gallery/mvfblt6r-667qht.webp', 'https://keystoneliv.com/public/uploads/property/ugU2mSy6BbqdiWgd8BB1RXRyQnRK5gqL2KtUlB81.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/neQCNkziS5bgoqGRmAb7yybVwaAKDFIUsnKt9779.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp", "https://keystoneliv.com/public/uploads/property/zp0VEmpHjp3nxN9ZDMZAsjt8sftwy04Pt0zchCPr.webp"]', 'Navyam is an under-construction residential project in Ravet, Pune 412101, on Survey No. 117, opposite S. B. Patil School, by Kiwale Realty LLP. It is planned on about 2.28 acres (9,210 sq m) with wings A to H and 203 apartments as filed with MahaRERA. The homes are 2 BHK with listed carpet areas of 753 to 773 sq ft and 3 BHK of about 1,053 sq ft, with the sales microsite showing prices from about Rs 85 lakh and Rs 1.15 crore all inclusive. Amenities include a clubhouse, indoor and outdoor gym, party lawn, children''s play area, yoga deck, cricket and multipurpose courts, walking track, amphitheatre, rainwater harvesting, CCTV and 24x7 security. The developer lists One Mall and Aundh Ravet Road about 2 minutes away, D-Mart Ravet and the Mumbai-Pune Expressway about 5 minutes, and Akurdi railway station about 10 minutes. The project is registered under MahaRERA number P52100054888 with a proposed completion date of 31 December 2029. Contact the Pune Home team for current availability, the latest price sheet and a site visit.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Sports Court", "Jogging Track", "Power Backup", "24x7 Security"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100054888"}, {"label": "Direct Starting Price", "value": "₹85 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "31 December 2029"}, {"label": "Micro-Market", "value": "Ravet, Pune"}]', '["MahaRERA: P52100054888", "0% Brokerage & Direct Builder Booking", "Ravet Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100054888', 11288, 'Verified', 'Pune');
