]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100047124"}, {"label": "Direct Starting Price", "value": "₹76.69 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Chinchwad, Pune"}]', '["MahaRERA: P52100047124", "0% Brokerage & Direct Builder Booking", "Chinchwad Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100047124', 10651, 'Verified', 'Pune');
